'use strict';
// A common, area-proportional composition chart. Detail tables retain all rows.
function compositionTreemap(items,{label='Composición del total',limit=10}={}){
 const all=items.filter(r=>Number.isFinite(r.value)&&r.value>0).sort((a,b)=>b.value-a.value),sum=all.reduce((s,r)=>s+r.value,0);
 if(!sum)return '<p class="notice">No hay importes positivos para representar esta composición.</p>';
 if(items.some(r=>r.value<0))return '<p class="notice">Hay importes negativos: consultá la tabla para leer la composición sin distorsionar las proporciones.</p>';
 const rows=all.slice(0,limit);if(all.length>limit)rows.push({name:`Resto · ${all.length-limit} categorías`,value:all.slice(limit).reduce((s,r)=>s+r.value,0),action:'',other:true});
 const palette=['#63338c','#8351a1','#246c7d','#8a671e','#52698c','#914075','#566936','#855237','#606773','#43695f','#75657e'];
 const rects=[];function divide(list,x,y,w,h){if(list.length===1){rects.push({...list[0],x,y,w,h});return;}const t=list.reduce((s,r)=>s+r.value,0);let n=1,a=list[0].value;while(n<list.length-1&&Math.abs(a+list[n].value-t/2)<Math.abs(a-t/2)){a+=list[n++].value;}const ratio=a/t;if(w*1.5>=h){divide(list.slice(0,n),x,y,w*ratio,h);divide(list.slice(n),x+w*ratio,y,w*(1-ratio),h);}else{divide(list.slice(0,n),x,y,w,h*ratio);divide(list.slice(n),x,y+h*ratio,w,h*(1-ratio));}}
 divide(rows.map((r,i)=>({...r,i})),0,0,100,100);
 return `<figure class="treemap-figure"><figcaption>${E(label)} <span>· 100% del total</span></figcaption><div class="rect-treemap" role="group" aria-label="${E(label)}. El área de cada rectángulo representa su participación.">${rects.map(r=>{const text=`${r.name}: ${pct(r.value/sum*100)}, ${money(r.value)}`,tiny=r.w<16||r.h<15;return `<button data-treemap-info="${E(text)}" class="treemap-tile ${tiny?'tiny-tile':''} ${r.w<40||r.h<25?'mobile-compact':''} ${r.w<10||r.h<8?'micro-tile':''}" ${r.action||''} style="left:${r.x}%;top:${r.y}%;width:${r.w}%;height:${r.h}%;background:${palette[r.i%palette.length]}" aria-label="${E(text)}" title="${E(text)}"><span class="tile-number" aria-hidden="true">${r.i+1}</span><span class="tile-name">${tiny?r.i+1:E(r.name)}</span><strong>${pct(r.value/sum*100)}</strong><small class="tile-amount">${short(r.value)}</small></button>`}).join('')}</div><p class="treemap-readout note" aria-live="polite"></p><ol class="treemap-key">${rows.map(r=>`<li><details><summary>${E(r.name)} · ${pct(r.value/sum*100)}</summary><p>${money(r.value)}</p></details></li>`).join('')}</ol>${all.length>limit?'<p class="note">Las categorías menores se agrupan en «Resto»; el detalle conserva todos los importes.</p>':''}</figure>`;
}
function caifPanel(){const d=state.caif?.periods?.[state.period];if(!d)return '';const closed=d.quarter===4,deficit=d.financialResult<0,max=Math.max(d.income,d.expense),steps=[['Ingresos corrientes',0,d.currentIncome,'income'],['Gastos corrientes',d.economicResult,d.currentIncome,'expense'],['Resultado económico',0,d.economicResult,'result'],['Ingresos de capital',d.economicResult,d.economicResult+d.capitalIncome,'income'],['Gastos de capital',d.financialResult,d.economicResult+d.capitalIncome,'expense'],['Resultado financiero',0,d.financialResult,'result']];const min=Math.min(0,d.financialResult),span=max-min;
 return `<section class="caif-panel ${deficit?'has-deficit':''}" aria-labelledby="caif-heading"><p class="eyebrow">${closed?'CIERRE':'ENERO–JUNIO'} ${d.year} · CUENTA AHORRO–INVERSIÓN</p><h2 id="caif-heading">${closed?`CABA cerró ${d.year} con ${deficit?'déficit':'superávit'} financiero.`:'El resultado de los primeros seis meses'}</h2><p class="snapshot-note">${E(d.status)} · importes nominales. Cálculo sobre el informe oficial.</p><div class="metrics"><div class="metric fiscal-result"><label>${deficit?'Déficit':'Superávit'} financiero</label><strong>${d.financialResult<0?'−':''}${money(Math.abs(d.financialResult))}</strong><small>${d.financialRatio<0?'−':''}${fmt(Math.abs(d.financialRatio),2)}% de los ingresos del período</small></div><div class="metric"><label>Ingresos realizados</label><strong>${money(d.income)}</strong><small>Recursos corrientes y de capital</small></div><div class="metric"><label>Gasto ejecutado</label><strong>${money(d.expense)}</strong><small>Gasto devengado, incluye pagos pendientes</small></div></div><p>${closed?'Los gastos del año':'Los gastos del semestre'} ${deficit?'superaron':'fueron inferiores a'} los ingresos en ${short(Math.abs(d.financialResult))}. ${d.economicResult>0?'Hubo ahorro corriente, pero el gasto de capital '+(deficit?'lo superó.':'no lo agotó.'):''}</p><div class="caif-waterfall" role="img" aria-label="Del ingreso corriente al resultado financiero. Valores en pesos nominales.">${steps.map(([name,a,b,kind])=>`<div class="waterfall-row"><span>${name}</span><div class="waterfall-track"><i class="waterfall-zero" style="left:${-min/span*100}%"></i><b class="${kind} ${(name==='Resultado financiero'&&deficit)?'negative':''}" style="left:${(Math.min(a,b)-min)/span*100}%;width:${Math.abs(b-a)/span*100}%"></b></div><strong>${short(name==='Resultado financiero'?d.financialResult:name==='Resultado económico'?d.economicResult:Math.abs(b-a))}</strong></div>`).join('')}</div><details><summary>Cómo se obtiene el resultado y qué incluye</summary><p>Resultado económico: ingresos corrientes menos gastos corrientes = ${money(d.economicResult)}. Resultado financiero: ese ahorro más los ingresos de capital, menos los gastos de capital = ${money(d.financialResult)}.</p><div class="table-wrap"><table><caption>Cuenta ahorro–inversión · ${d.year} · pesos nominales</caption><thead><tr><th>Concepto</th><th>Importe</th></tr></thead><tbody>${[['Ingresos corrientes',d.currentIncome],['Gastos corrientes (incluyen intereses)',d.currentExpense],['Resultado económico',d.economicResult],['Ingresos de capital',d.capitalIncome],['Gastos de capital',d.capitalExpense],['Ingresos totales',d.income],['Gastos totales',d.expense],['Resultado financiero',d.financialResult]].map(([name,value])=>`<tr><th scope="row">${name}</th><td class="num">${money(value)}</td></tr>`).join('')}</tbody></table></div><p>${E(state.caif.scope)}</p><p>${E(state.caif.method)} ${E(d.status)}. Pesos nominales de ${d.year}.</p><p>${E(d.rounding.method)}</p><p><a href="${E(d.localSource)}" target="_blank" rel="noopener">Informe oficial del período</a> · <a href="/data/caif.json" download>Valores, fórmulas y fuentes</a></p></details></section>`;
}
